check_argv:
const fs=require("node:fs"),path=require("node:path"),m=require("node:module"),u=require("node:url");
(async()=>{
try{
const file=path.resolve(process.argv[2]||process.argv[1]);
if(!fs.existsSync(file)){console.error("file not found: "+file);process.exit(2);}
const req=m.createRequire(path.join(path.dirname(file),"a.js"));
let prettierPath,pluginPath;
try{prettierPath=req.resolve("prettier");}catch(e){console.error("prettier not resolvable from "+file+" (install it as project devDependency): "+e.message);process.exit(2);}
try{pluginPath=req.resolve("@shopify/prettier-plugin-liquid");}catch(e){console.error("@shopify/prettier-plugin-liquid not resolvable from "+file+" (install it as project devDependency): "+e.message);process.exit(2);}
const prettier=req(prettierPath);
let plugin=await import(u.pathToFileURL(pluginPath).href);
plugin=plugin.default||plugin;
const src=fs.readFileSync(file,"utf8");
let config=null;
try{config=await prettier.resolveConfig(file);}catch(e){config=null;}
const options=Object.assign({},config||{},{parser:"liquid-html",plugins:[plugin]});
let out;
try{out=await prettier.format(src,options);}catch(e){console.error("prettier format error: "+e.message);process.exit(2);}
process.exit(out===src?0:1);
}catch(e){console.error("wrapper error: "+(e&&e.message));process.exit(2);}
})();

